// Sigil & Spark v3/v4 — loose audio for the story: voices, music, ambience and sound effects played straight from WAV files in
// Content/PBX/StoryAudio/<kind>/<name>.wav (generated by tools/story/*: Kokoro voices, converted CC0/CC-BY music, synthesised
// ambience). No editor import step: regenerate a line and it plays. 16-bit PCM, mono or stereo, any sample rate.
#pragma once
#include "CoreMinimal.h"
class USoundWaveProcedural; class UObject;

namespace PBXAudio
{
	FString Path(const TCHAR* Kind, const FString& Name);                 // Content/PBX/StoryAudio/<Kind>/<Name>.wav
	bool Exists(const TCHAR* Kind, const FString& Name);
	/** a playable sound for that file (cached PCM); bLoop re-queues the samples when they run out. nullptr if missing/bad */
	USoundWaveProcedural* Load(UObject* Outer, const TCHAR* Kind, const FString& Name, bool bLoop, float* OutSeconds = nullptr);
}
